css:
:host { --paper: #f2eee4; --ink: #293a36; --muted: #68716a; --accent: #a45238; --gold: #c7ad78; --dark: #1e3532; --line: #cecfc1; --serif: "Songti SC","STSong","Noto Serif CJK SC",serif; --sans: "PingFang SC","Microsoft YaHei",sans-serif; }
* { box-sizing: border-box; }
body { margin: 0px; background: rgb(220, 222, 214); color: var(--ink); font: 18px/1.6 var(--sans); }
button, a { -webkit-tap-highlight-color: transparent; }
button { font: inherit; cursor: pointer; color: inherit; }
button:focus-visible, a:focus-visible, video:focus-visible { outline: 3px solid var(--accent); outline-offset: 5px; }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; object-fit: contain; }
figure, p, h1, h2, h3 { margin: 0px; }
button[data-zoom] { background: none; border: 0px; padding: 0px; display: block; width: 100%; transition: filter 0.2s; }
button[data-zoom]:hover { filter: brightness(0.93); }
button[data-zoom] img { width: 100%; height: 100%; object-fit: contain; }
video { display: block; width: 100%; background: rgb(16, 26, 24); object-fit: contain; }
h1, h2, h3 { font-weight: 600; }
h1 { font: 600 66px/1.2 var(--serif); letter-spacing: 2px; }
h2 { font-size: 30px; line-height: 1.4; }
h3 { font-size: 24px; }
p { font-size: 24px; line-height: 1.75; }
small { font-size: 20px; }
figcaption { color: var(--muted); font-size: 20px; margin-top: 15px; }
.site-header { height: 66px; background: rgb(250, 248, 242); display: flex; align-items: center; justify-content: space-between; padding: 0px 30px; border-bottom: 1px solid rgb(214, 215, 206); }
.brand { display: flex; align-items: center; gap: 16px; }
.brand b { font-size: 19px; }
.seal { background: var(--accent); color: var(--paper); padding: 0px 7px; font: 24px/36px var(--serif); }
.brand-note, .header-note { font-size: 13px; color: var(--muted); }
.viewport { height: calc(100dvh - 132px); display: flex; align-items: center; justify-content: center; overflow: hidden; }
.stage-wrap { position: relative; flex-shrink: 0; }
#stage { width: 1920px; height: 1080px; transform-origin: left top; }
.slide { display: none; width: 1920px; height: 1080px; padding: 76px 96px 90px; background: var(--paper); position: relative; overflow: hidden; }
.slide.active { display: block; }
.dark { background: var(--dark); color: var(--paper); --muted: #bac4b7; --line: #587068; --accent: #dfab7c; }
.slide-head { margin-bottom: 48px; }
.eyebrow { color: var(--accent); font-size: 21px; letter-spacing: 3px; font-weight: 600; margin-bottom: 22px; }
.slide-head h1 { margin-bottom: 20px; }
.slide-head > p:last-child { color: var(--muted); font-size: 25px; }
.folio { position: absolute; bottom: 32px; left: 96px; right: 96px; border-top: 1px solid var(--line); padding-top: 16px; display: flex; justify-content: space-between; font-size: 17px; letter-spacing: 1px; color: var(--muted); }
.page-nav { height: 66px; display: flex; align-items: center; justify-content: center; gap: 24px; background: rgb(250, 248, 242); }
.page-nav > button { padding: 8px 18px; background: none; border: 1px solid rgb(199, 203, 191); font-size: 14px; min-height: 44px; }
.page-nav button:disabled { opacity: 0.3; cursor: default; }
#chapter-nav { display: flex; gap: 6px; }
#chapter-nav button { border: 0px; background: transparent; padding: 10px; min-width: 44px; min-height: 44px; font-size: 14px; }
#chapter-nav button.active { background: var(--ink); color: var(--paper); }
#page-count { font-size: 13px; color: var(--muted); }
.fine-note { font-size: 19px; color: var(--muted); }
.pair-arrow { font-size: 40px; color: var(--accent); }
h2 small { color: var(--accent); font: 20px var(--sans); margin-right: 20px; }
i { font-style: normal; }
.media-heading, .image-label { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
.media-heading > span, .image-label { font-size: 18px; color: var(--muted); }
.cover { padding-top: 54px; }
.cover-type { display: flex; justify-content: space-between; position: relative; z-index: 2; font-size: 17px; letter-spacing: 3px; padding-bottom: 22px; border-bottom: 1px solid var(--line); width: 100%; }
.cover-type > span { color: rgb(224, 218, 199); }
.cover-copy { position: relative; z-index: 2; width: 850px; padding-top: 72px; }
.cover h1 { font-size: 152px; line-height: 1.14; letter-spacing: 13px; margin: 14px 0px 30px; }
.red-dot { color: var(--accent); }
.cover h2 { font-size: 36px; letter-spacing: 3px; }
.cover-intro { font-size: 24px; color: var(--muted); margin-top: 28px; }
.text-link { display: inline-flex; gap: 70px; border-bottom: 1px solid var(--accent); margin-top: 28px; padding: 0px 0px 9px; font-size: 22px; color: var(--accent); }
.cover-visual { position: absolute; inset: 0px 0px 0px 985px; background: var(--dark); overflow: hidden; }
.cover-visual img { position: absolute; width: 840px; height: 845px; left: 35px; top: 96px; z-index: 1; }
.circle { position: absolute; border: 1px solid rgb(112, 133, 117); border-radius: 50%; width: 730px; height: 730px; left: 85px; top: 140px; opacity: 0.45; }
.c2 { transform: scale(1.09); }
.c3 { transform: scale(1.18); opacity: 0.2; }
.visual-index { position: absolute; bottom: 128px; left: 165px; color: rgb(214, 198, 158); font-size: 20px; letter-spacing: 5px; }
.cover-role { position: absolute; left: 96px; right: 1000px; bottom: 117px; display: flex; gap: 32px; border-top: 1px solid var(--line); padding-top: 20px; }
.cover-role small { display: block; font-size: 16px; color: var(--muted); margin-bottom: 7px; }
.cover-role b { font-size: 19px; font-weight: 500; }
.cover-role > div:first-child { min-width: 100px; }
.cover-role > div:nth-child(2) { max-width: 390px; }
.cover .folio { right: 1000px; font-size: 15px; }

.concept-layout { display: grid; grid-template-columns: 610px 1fr; gap: 80px; height: 635px; }
.concept-left { border-right: 1px solid var(--line); padding-right: 58px; }
.statement { display: flex; gap: 28px; }
.large-number { font: 62px/1 var(--serif); color: var(--accent); opacity: 0.65; }
.statement p { font-size: 23px; color: var(--muted); margin-top: 16px; }
.reference-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px 30px; width: 430px; margin: 32px 0px 0px 86px; }
.reference-grid button { height: 158px; }
.reference-grid img { object-fit: cover !important; object-position: center 32%; }
.reference-grid figcaption { font-size: 17px; margin-top: 7px; }
.state-pair { display: grid; grid-template-columns: 1fr 50px 1fr; align-items: center; gap: 16px; margin: 43px 0px 38px; }
.state-pair figure > img { width: 100%; height: 252px; object-fit: cover; }
.state-pair figcaption { font-size: 18px; }
.state-pair figcaption span { color: var(--accent); margin-right: 10px; }
.concept-chain { display: flex; justify-content: space-between; align-items: center; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: 22px 0px; font-size: 25px; }
.concept-chain i { color: var(--accent); }
.concept-right .fine-note { margin-top: 24px; }
.reference-grid img { background: rgb(232, 227, 215); object-fit: contain !important; }
.state-pair figure > img { object-fit: contain; background: rgb(38, 51, 46); }
.drawing-layout { display: grid; grid-template-columns: 1.12fr 1fr; gap: 64px; height: 630px; }
.drawing-main { border-right: 1px solid var(--line); padding-right: 56px; }
.composition { height: 450px; margin-top: 25px; }
.drawing-caption { display: flex; justify-content: space-between; margin-top: 20px; border-top: 1px solid var(--line); padding-top: 24px; color: var(--muted); font-size: 22px; }
.drawing-side .details { height: 324px; margin-top: 24px; }
.sketch-note { display: flex; align-items: center; justify-content: center; gap: 44px; margin-top: 15px; }
.sketch-note > button { height: 236px; width: 245px; }
.sketch-note p { color: var(--muted); font-size: 22px; margin-top: 10px; }
.motion-layout { display: grid; grid-template-columns: 610px 1fr; gap: 74px; margin-top: 65px; }
.motion-left button { height: 258px; margin: 28px 0px 24px; }
.motion-left > p { color: var(--muted); font-size: 24px; }
.motion-steps { display: flex; justify-content: space-between; margin-top: 45px; border-top: 1px solid var(--line); padding-top: 30px; font-size: 22px; }
.motion-steps i { color: var(--accent); }
.motion-right video { height: 534px; }
.motion-right figcaption { font-size: 21px; }
.ensemble-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 70px; height: 650px; }
.restoration { border-right: 1px solid var(--line); padding-right: 64px; }
.mural-strip { height: 110px; }
.down-label { text-align: center; color: var(--accent); font-size: 24px; margin: 4px 0px; }
.down-label span { font-size: 18px; margin-left: 12px; }
.ensemble-image { height: 452px; }
.instrument-side > h2 { margin: 14px 0px 18px; }
.instrument-side > p { font-size: 24px; color: var(--muted); }
.instrument-side > button { height: 258px; margin: 12px 0px 18px; }
.instrument-list { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.instrument-list span { font-size: 23px; border-bottom: 1px solid var(--line); padding-bottom: 13px; }
.instrument-list b { font-size: 15px; margin-right: 15px; color: var(--accent); font-weight: 400; }
.instrument-conclusion { font-size: 23px; margin-top: 34px; display: flex; justify-content: space-between; }
.instrument-conclusion i { color: var(--accent); }
.flow-slide .slide-head { margin-bottom: 30px; }
.music-module { padding: 28px 38px; background: var(--dark); color: var(--paper); }
.music-top { display: flex; align-items: center; gap: 25px; }
.play-disc { display: grid; place-items: center; border: 1px solid var(--gold); width: 65px; height: 65px; border-radius: 50%; font: 40px var(--serif); color: var(--gold); }
.music-top h2 { font-size: 25px; }
.music-top p { font-size: 18px; color: rgb(188, 200, 191); }
.module-note { margin-left: auto; font-size: 17px; color: rgb(189, 199, 191); }
.score-track { position: relative; display: flex; justify-content: space-between; border-top: 3px solid rgb(131, 148, 132); margin: 28px 10px 0px; padding-top: 16px; font-size: 18px; }
.score-track > span:not(.track-fill) { z-index: 1; position: relative; }
.score-track > span:not(.track-fill)::before { content: ""; position: absolute; top: -22px; left: 50%; width: 9px; height: 9px; border-radius: 50%; background: var(--gold); }
.track-fill { position: absolute; height: 3px; width: 8%; background: rgb(238, 215, 162); left: 0px; top: -3px; transition: width 0.4s; }
.playhead { position: absolute; width: 16px; height: 16px; left: 8%; top: -9px; border-radius: 50%; background: rgb(238, 215, 162); transition: left 0.4s; }
.track-label { display: flex; justify-content: space-between; font-size: 14px; color: rgb(174, 190, 179); margin-top: 15px; }
.flow-body { display: grid; grid-template-columns: 1.1fr 1fr; gap: 55px; margin-top: 35px; }
.stage-tabs { display: flex; gap: 16px; }
.stage-tabs button { flex: 1 1 0%; text-align: left; border-right-color: ; border-right-style: ; border-right-width: ; border-bottom-color: ; border-bottom-style: ; border-bottom-width: ; border-left-color: ; border-left-style: ; border-left-width: ; border-image-source: ; border-image-slice: ; border-image-width: ; border-image-outset: ; border-image-repeat: ; border-top: 3px solid var(--line); padding: 17px 18px; background: none; transition: background 0.2s; }
.stage-tabs button.selected { border-color: var(--accent); background: rgb(233, 224, 204); }
.stage-tabs svg { fill: none; stroke: var(--accent); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; width: 47px; height: 47px; margin-bottom: 10px; }
.stage-tabs small { display: block; font-size: 17px; color: var(--muted); margin-bottom: 7px; }
.stage-tabs b { font-size: 23px; font-weight: 500; }
.step-description { margin-top: 20px; min-height: 80px; font-size: 22px; color: var(--muted); }
.signal-path { display: flex; justify-content: space-between; border-top: 1px solid var(--line); padding-top: 20px; font-size: 19px; }
.signal-path strong { color: var(--accent); font-weight: 500; }
.flow-explain .fine-note { margin-top: 20px; font-size: 16px; }
.flow-video video { height: 356px; }
.flow-video figcaption { font-size: 18px; }
.technical-layout { display: grid; grid-template-columns: 1140px 1fr; gap: 65px; margin-top: 55px; }
.td-evidence { height: 640px; }
.technical-notes article { display: flex; gap: 28px; border-top: 1px solid var(--line); padding: 23px 0px; margin-bottom: 10px; }
.technical-notes article > span { font: 36px var(--serif); color: var(--gold); }
.technical-notes h2 { font-size: 29px; }
.technical-notes p { font-size: 23px; color: var(--muted); margin-top: 12px; }
.technical-notes .fine-note { font-size: 17px; margin-top: 20px; }
.td-evidence { position: relative; overflow: hidden; background: rgb(34, 38, 41); aspect-ratio: 1140 / 640; }
.td-evidence img { position: absolute; max-width: none; left: -45%; top: -26%; width: 151% !important; height: auto !important; }
.scene-layout { display: grid; grid-template-columns: 720px 1fr; gap: 75px; margin-top: 65px; }
.scene-layout article > button { height: 365px; margin-top: 28px; }
.scene-layout article > p { font-size: 23px; color: var(--muted); margin-top: 28px; }
.scene-summary { display: flex; justify-content: space-between; border-top: 1px solid var(--line); padding-top: 24px; margin-top: 32px; font-size: 22px; }
.scene-summary i { color: var(--accent); }
.scene-layout video { height: 527px; }
.live-layout { display: grid; grid-template-columns: 1100px 1fr; gap: 65px; margin-top: 45px; }
.live-layout > figure > video { height: 618px; }
.live-photos { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.retained-photo { height: 182px; overflow: hidden; background: rgb(38, 55, 49); }
.retained-photo svg { display: block; }
.live-photos figcaption { font-size: 18px; }
.contribution { border-top: 1px solid var(--line); margin-top: 32px; padding-top: 27px; }
.contribution .eyebrow { font-size: 18px; letter-spacing: 1px; margin-bottom: 12px; }
.contribution h2 { font-size: 28px; }
.contribution > div { display: grid; grid-template-columns: 1fr 1fr; gap: 16px 20px; margin: 24px 0px; font-size: 22px; }
.contribution > div > span::before { content: "·"; margin-right: 15px; color: var(--gold); }
.contribution > p:last-child { font-size: 22px; color: var(--muted); }
dialog { background: var(--paper); border: 0px; padding: 24px; max-width: 92vw; max-height: 94dvh; color: var(--ink); }
dialog::backdrop { background: rgba(16, 28, 25, 0.875); }
#image-large { max-height: 78dvh; max-width: 86vw; margin: auto; }
#image-close { display: block; margin: 0px 0px 18px auto; border: 1px solid var(--line); padding: 6px 14px; background: transparent; }
#image-caption { font-size: 16px; text-align: center; margin-top: 14px; }
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; scroll-behavior: auto !important; }
}

.reference-grid img { object-fit: cover !important; object-position: center 32%; }


:host { --paper: #f5f0e6; --ink: #3d352e; --muted: #766b5e; --accent: #a34f35; --gold: #9b7550; --dark: #3d352e; --line: #d8cdbb; }
body { background: rgb(229, 222, 210); }
.site-header, .page-nav { background: rgb(250, 247, 240); }
.site-header { border-bottom-color: rgb(216, 205, 187); }
.page-nav > button { border-color: rgb(207, 195, 177); }
.slide, .slide.dark { color: var(--ink); background-color: var(--paper); background-image: radial-gradient(at 90% 12%, rgba(193, 155, 100, 0.07), transparent 62%), repeating-linear-gradient(0deg, rgba(112, 89, 59, 0.02) 0px, rgba(112, 89, 59, 0.02) 1px, transparent 1px, transparent 4px), repeating-linear-gradient(92deg, rgba(112, 89, 59, 0.01) 0px, rgba(112, 89, 59, 0.01) 1px, transparent 1px, transparent 7px); }
.dark { --muted: #766b5e; --line: #d8cdbb; --accent: #a34f35; }
.cover-visual { background: transparent; }
.cover-type > span { color: var(--muted); }
.circle { border-color: rgb(174, 144, 101); opacity: 0.2; }
.c2 { opacity: 0.13; }
.c3 { opacity: 0.08; }
.visual-index { color: rgb(138, 99, 67); }
.reference-grid img, .state-pair figure > img, .retained-photo { background: rgb(232, 223, 208); }
video { background: rgb(33, 30, 27); }
.td-evidence { background: rgb(41, 39, 36); }
.music-module { background: rgb(235, 225, 208); color: var(--ink); border: 1px solid rgb(216, 200, 175); }
.music-top p, .module-note, .track-label { color: rgb(118, 102, 81); }
.play-disc { color: var(--accent); border-color: rgb(179, 141, 98); }
.score-track { border-top-color: rgb(200, 181, 149); }
.score-track > span:not(.track-fill)::before { background: rgb(162, 128, 84); }
.track-fill, .playhead { background: var(--accent); }
.stage-tabs button.selected { background: rgb(239, 226, 207); }
.contribution > div > span::before { color: var(--accent); }
dialog::backdrop { background: rgba(39, 32, 26, 0.86); }
html, body { margin: 0px !important; padding: 0px !important; overflow: visible !important; }
.stage-wrap, .stage-shell, #stage { width: 1920px !important; height: 1080px !important; transform: none !important; margin: 0px !important; }
.stage, .sheet { transform: none !important; }
.sheet-wrap { width: 1920px !important; height: 1080px !important; margin: 0px !important; }
#portfolio { width: 1920px !important; max-width: none !important; margin: 0px !important; padding: 0px !important; }
